<?php

namespace Schemastud\Frame\Vocabulary;

use JsonException;

/**
 * Reads a host's widget vocabulary file: `resources/frame/vocabulary.json` by default, moved by the `frame.vocabulary`
 * config key (ticket 05, rulings 1 and 2). The file is GENERATED by `@schemastud/frame`'s `frame-vocabulary` command;
 * PHP only reads it, and TypeScript never does.
 *
 * It answers whether a name is bound in a context, which node types a stock name is valid on there, and which
 * contexts, form modes, reserved names and wire keys the file lists. A missing or unreadable file is a
 * {@see VocabularyState} it reports, never an exception: on such a file every name reads as unbound and every list as
 * empty, so a caller asks {@see self::isReadable()} first.
 *
 * The file's shape (version 1):
 *
 *     { "version": 1, "contexts": [...], "formModes": [...], "reserved": [...],
 *       "widgets": { "<name>": [ { "contexts"?: [...], "stock"?: [...] }, ... ] },
 *       "conflicts"?: { "<name>": ["<context>", ...] }, "reads"?: [...] }
 *
 * A name maps to its registrations in the order they win; `contexts` absent means unscoped; `stock` present means the
 * registration resolves to an RJSF stock name valid on those node types. `reads` is ruling 6's list of the wire keys
 * the host's JS build reads.
 *
 * Laravel-free on purpose apart from {@see self::fromConfig()}: it is a plain reader with no doctor dependency.
 */
final class WidgetVocabulary
{
    /** The file version this reader reads (ruling 2). {@see self::version()} returns the file's own; the audit compares. */
    public const Version = 1;

    /**
     * @param  array<string, mixed>  $data  the decoded file; empty unless the state is Readable
     */
    private function __construct(
        public readonly VocabularyState $state,
        public readonly string $path,
        private readonly array $data = [],
        public readonly ?string $error = null,
    ) {}

    /** The file at `config('frame.vocabulary')`; a relative path is resolved against the application's base path. */
    public static function fromConfig(): self
    {
        $path = (string) config('frame.vocabulary', resource_path('frame/vocabulary.json'));

        if ($path !== '' && ! str_starts_with($path, '/') && ! preg_match('/^[A-Za-z]:[\\\\\/]/', $path)) {
            $path = base_path($path);
        }

        return self::fromFile($path);
    }

    public static function fromFile(string $path): self
    {
        if (! is_file($path)) {
            return new self(VocabularyState::Missing, $path);
        }

        $raw = @file_get_contents($path);

        if ($raw === false) {
            return new self(VocabularyState::Unreadable, $path, error: 'the file could not be read');
        }

        try {
            $data = json_decode($raw, true, 512, JSON_THROW_ON_ERROR);
        } catch (JsonException $e) {
            return new self(VocabularyState::Unreadable, $path, error: 'invalid JSON: '.$e->getMessage());
        }

        if (! is_array($data) || array_is_list($data)) {
            return new self(VocabularyState::Unreadable, $path, error: 'the file is not a JSON object');
        }

        return new self(VocabularyState::Readable, $path, $data);
    }

    public function isReadable(): bool
    {
        return $this->state === VocabularyState::Readable;
    }

    /** The file's `version`, or null when it is absent, not an integer, or the file is not readable. */
    public function version(): ?int
    {
        $version = $this->data['version'] ?? null;

        return is_int($version) ? $version : null;
    }

    /** @return list<string> */
    public function contexts(): array
    {
        return $this->strings('contexts');
    }

    /** @return list<string> */
    public function formModes(): array
    {
        return $this->strings('formModes');
    }

    /** @return list<string> */
    public function reserved(): array
    {
        return $this->strings('reserved');
    }

    /**
     * The wire keys the host's JS build reads (ruling 6's `reads`), possibly empty. Null when the file has no `reads`
     * (written before ruling 6's slice 8): the wire-keys check is inconclusive, never a finding per key. Also null on a
     * file that is not readable.
     *
     * @return list<string>|null
     */
    public function wireKeys(): ?array
    {
        if (! $this->isReadable() || ! array_key_exists('reads', $this->data)) {
            return null;
        }

        return $this->strings('reads');
    }

    /** Every name the file binds, in file order. @return list<string> */
    public function names(): array
    {
        $widgets = $this->data['widgets'] ?? [];

        return is_array($widgets) ? array_values(array_map('strval', array_keys($widgets))) : [];
    }

    /** The contexts the file lists for this name under `conflicts`. @return list<string> */
    public function conflicts(string $name): array
    {
        $conflicts = $this->data['conflicts'] ?? [];
        $contexts = is_array($conflicts) ? ($conflicts[$name] ?? []) : [];

        return is_array($contexts) ? array_values(array_filter($contexts, 'is_string')) : [];
    }

    /** Is this name bound in this context: its {@see WidgetBinding}. */
    public function binding(string $name, string $context): WidgetBinding
    {
        $registrations = $this->registrations($name);
        $scoped = null;
        $unscoped = null;

        foreach ($registrations as $registration) {
            $contexts = $registration['contexts'] ?? null;

            if ($contexts === null) {
                $unscoped ??= $registration;
            } elseif (is_array($contexts) && in_array($context, $contexts, true)) {
                $scoped ??= $registration;
            }
        }

        $answer = $scoped ?? $unscoped;

        if ($answer === null) {
            return WidgetBinding::unbound();
        }

        if (in_array($context, $this->conflicts($name), true)) {
            return new WidgetBinding(true, conflicted: true);
        }

        $stock = $answer['stock'] ?? null;

        return new WidgetBinding(true, nodeTypes: is_array($stock) ? array_values(array_filter($stock, 'is_string')) : null);
    }

    /** @return list<array<string, mixed>> */
    private function registrations(string $name): array
    {
        $widgets = $this->data['widgets'] ?? [];
        $registrations = is_array($widgets) ? ($widgets[$name] ?? []) : [];

        return is_array($registrations) ? array_values(array_filter($registrations, 'is_array')) : [];
    }

    /** @return list<string> */
    private function strings(string $key): array
    {
        $list = $this->data[$key] ?? [];

        return is_array($list) ? array_values(array_filter($list, 'is_string')) : [];
    }
}
